% The COBRAToolbox: This script tests the functionality of 
%                   calculateFluxShifts.m function
%
% Purpose:
%     - For testing the IgemRNA post-optimization task called "Calculate flux
%     shifts between phenotypes" which calculates flux differences for each
%     reaction from two (or more if target = "All") result model files generated by createContextSpecificModel.m. 
%
% Function under test:
%     src/analysis/igemRNA/calculateFluxShifts/calculateFluxShifts.m
%
% Tier (Constitution III-Coverage):
%     Tier 1 - no model and no optimisation; result files from this folder, and small result files
%     written to a temporary folder for the target "All" and for a file without flux columns.
%
% Coverage exemptions:
%     None. Every executable line is reached below.
%
% Known defects documented (NOT tested, NOT fixed here):
%     None found.
%
% Authors:
%     - Kristina Grausa 05/16/2022 - created 
%     - Kristina Grausa 08/22/2022 - standard header and formatting
%     - Farid Zare      02/12/2024 - Repository address corrected
%     - Coverage completed by feature 20261104-115314-test-coverage-100, 2026-11-04.
%

global CBTDIR

% define the required solvers
requiredSolvers = {'needsLP', 'matlab'};

% check if the specified requirements are fullfilled
solvers = prepareTest('needsLP',true);

% save the current path and initialize the test
currentDir = cd(fileparts(which(mfilename)));

% determine the test path for references
testPath = pwd;

% set the tolerance
tol = 1e-8;

% set function params
source = {'SRR8994357_WT';};
target = {'SRR8994378_S47D';};

% Load Reference Data
load('refData_flux_shifts.mat');

% the result folder is created by the function, also when an earlier run was interrupted
resultFolder = fullfile('resultsPostOptimization', 'fluxShifts');
if isfolder(resultFolder)
    rmdir(resultFolder, 's');
end

for k = 1:length(solvers.LP)
    solverLPOK = changeCobraSolver(solvers.LP{k}, 'LP', 0);

    if solverLPOK
       calculateFluxShifts(source, target);
       
       fprintf(' -- Running testFluxShifts.m using the solver interface: %s ... ', solvers.LP{k});

       % load the result
       resultPath = ['resultsPostOptimization', filesep, 'fluxShifts', filesep, 'SRR8994378_S47D_flux_shifts.xls'];
       resultData = readtable(resultPath);
       
       % Compare the result with reference data
       assert(isequaln(refData, resultData));
       
       % output a success message
       fprintf('Done.\n');
    end
end

% remove the results written in this folder
rmdir(resultFolder, 's');

%% target "All": every other model file is compared with the source

% small result files in a temporary folder: the source, one target and a file without flux columns
workDir = tempname;
mkdir(fullfile(workDir, 'resultsPostOptimization', 'contextSpecificModels'));
cd(workDir);
modelFolder = fullfile('resultsPostOptimization', 'contextSpecificModels');
columns = {'Reaction', 'MinFlux', 'MaxFlux'};
writetable(cell2table({'R1', '1', '2'; 'R2', '0', '0'; 'R3', '2', '4'; 'R4', '0', '0'}, 'VariableNames', columns), ...
           fullfile(modelFolder, 'toySource.xls'), 'Sheet', 'Reaction List');
writetable(cell2table({'R1', '2', '1'; 'R2', '3', '5'; 'R3', '0', '0'; 'R4', '0', '0'}, 'VariableNames', columns), ...
           fullfile(modelFolder, 'toyTarget.xls'), 'Sheet', 'Reaction List');
writetable(cell2table({'R1'; 'R2'}, 'VariableNames', {'Reaction'}), ...
           fullfile(modelFolder, 'toyBroken.xls'), 'Sheet', 'Reaction List');

printed = evalc('calculateFluxShifts({''toySource''}, ''All'');');

% only the target gets a result: not the source, and not the file without flux columns, whose error
% is displayed and does not stop the comparison
results = dir(fullfile('resultsPostOptimization', 'fluxShifts', '*.xls'));
assert(isequal({results.name}, {'toyTarget_flux_shifts.xls'}));
assert(contains(printed, 'MinFlux'));

% the ratios of the target to the source: a number, 'up' for a source of 0, 'down' for a target of 0
% and 1 when both are 0; the source fluxes are added as columns
shifts = readcell(fullfile(results(1).folder, results(1).name));
assert(isequal(shifts(1, :), {'Reaction', 'MinFlux', 'MaxFlux', 'MinFlux_toySource', 'MaxFlux_toySource', ...
                              'MinFluxRatio', 'MaxFluxRatio'}));
assert(isequal(shifts(2:end, 1), {'R1'; 'R2'; 'R3'; 'R4'}));
assert(isequal(shifts(2:end, 6), {2; 'up'; 'down'; 1}));
assert(isequal(shifts(2:end, 7), {0.5; 'up'; 'down'; 1}));
assert(isequal(shifts(2:end, 4:5), {1, 2; 0, 0; 2, 4; 0, 0}));

cd(testPath);
rmdir(workDir, 's');

% change the directory
cd(currentDir);
